def fold_list(head: "ListNode | None") -> None:
    node = head
    while node is not None and node.next is not None and node.next.next is not None:
        before_last = node
        while before_last.next.next is not None:   # walk to the node before the tail
            before_last = before_last.next
        last = before_last.next
        before_last.next = None
        last.next = node.next                      # move the tail right after node
        node.next = last
        node = last.next


